```rust
fn run(cli: Cli) -> Result<()> {
    // Load configuration from .mlt.toml (or --config path).
    let config = load_config(cli.config.as_deref())?;

    // Build rule registry from configuration (only enabled rules).
    let rules = mlt_rules::active_rules(&config);
    let registry = RuleRegistry::new(rules, &config);
    let mut linter = Linter::new(registry);

    let mut total_diagnostics = 0;
    let mut files_with_issues = 0;

    for file_path in &cli.files {
        let source = match fs::read_to_string(file_path) {
            Ok(s) => s,
            Err(e) if e.kind() == io::ErrorKind::NotFound => {
                // NOFIL (Incomplete Analysis 3.6): the file does not exist.
                // Emit a per-file diagnostic instead of aborting the whole run.
                let diag = Diagnostic {
                    rule_id: "NOFIL",
                    message: format!(
                        "Unable to open file {}. File is not found.",
                        file_path.display()
                    ),
                    severity: Severity::Error,
                    byte_range: 0..1,
                    line: 1,
                    column: 1,
                    fix: None,
                };
                print_diagnostic(file_path, &diag);
                total_diagnostics += 1;
                files_with_issues += 1;
                continue;
            }
            Err(e) => {
                // Other I/O errors (e.g., permission denied): abort the run.
                // This is the future home of the RDERR diagnostic (see RDERR plan).
                return Err(e)
                    .with_context(|| format!("failed to read {}", file_path.display()));
            }
        };

        let diagnostics = linter
            .lint(&source, file_path)
            .with_context(|| format!("failed to parse {}", file_path.display()))?;

        if diagnostics.is_empty() {
            continue;
        }

        if cli.fix {
            let fixed = apply_fixes(&source, &diagnostics);
            fs::write(file_path, &fixed)
                .with_context(|| format!("failed to write {}", file_path.display()))?;

            let fix_count = diagnostics.iter().filter(|d| d.fix.is_some()).count();
            println!(
                "Fixed {} issue{} in {}",
                fix_count,
                if fix_count == 1 { "" } else { "s" },
                file_path.display()
            );
        } else {
            for diag in &diagnostics {
                print_diagnostic(file_path, diag);
            }
        }

        total_diagnostics += diagnostics.len();
        files_with_issues += 1;
    }

    if !cli.fix && total_diagnostics > 0 {
        println!(
            "\nFound {} issue{} in {} file{}.",
            total_diagnostics,
            if total_diagnostics == 1 { "" } else { "s" },
            files_with_issues,
            if files_with_issues == 1 { "" } else { "s" },
        );
        process::exit(1);
    }

    Ok(())
}
```

